select public.prepify_load_bank('Chemistry', 1, $j$[["A chemist is studying the metabolic reactions in a human cell. What is this branch of chemistry called?",["inorganic Chemistry","Biochemistry","Physical Chemistry","Analytical Chemistry"],"B",3,1,"463ab4d1666f",1],["Organic chemistry is defined as the study of substances containing carbon, but which of these is usually excluded?",["Proteins","Carbohydrates","Synthetic Polymers","Carbonates and Bicarbonates"],"D",3,0,"143ccbe6a8c3",1],["Which of these is a primary goal of chemistry?",["Only studying living things","Avoiding the use of technology","Ignoring the study of energy","Investigating the changes that materials undergo"],"D",3,0,"8eea81e1a73a",1],["A scientist is looking at the chemical changes that occur in the human body. This falls under:",["Physical Chemistry","Organic Chemistry","Biochemistry","Analytical Chemistry"],"C",3,1,"32e098ce7d6e",1],["If a substance contains carbon but is an oxide, it is typically classified under:",["Organic Chemistry","Inorganic Chemistry","Geochemistry","Nuclear Chemistry"],"B",3,1,"4465c786f8ce",1],["Environmental Chemistry is closely linked to studying:",["How to create more hazardous waste","Toxic substances that pollute the environment","Only nuclear reactions","Physical laws of motion"],"B",3,0,"d948f757e20c",1],["Chemistry helps us understand:",["Natural phenomena","How to avoid chemical changes","Only the study of math","How to ignore properties of matter"],"A",3,0,"c48c61baba6b",1],["\"Green chemistry\" models processes that:",["Reduce the use of hazardous substances","Use hazardous substances","Increase pollution","Only focus on biochemistry"],"A",3,0,"be2e67fdce56",1],["What does chemistry investigate regarding matter?",["Only its composition","Only its structure","Only its interactions with energy","Its composition, structure, properties, and interactions"],"D",3,0,"67c8a6076a7d",1],["A pharmaceutical company is developing a new medicine to target a specific protein in the body. Which branch is most involved?",["Geochemistry","Medicinal Chemistry","Analytical Chemistry","Nuclear Chemistry"],"B",3,0,"ff065a04e5c9",1],["A scientist discovers a new reaction in the laboratory. Turning that discovery into a useful product is mainly an example of:",["Technology using scientific knowledge","Science only","Engineering only","Technology only"],"A",3,1,"5d0908fcd631",1],["Designing machinery for manufacturing detergents is mainly the work of:",["Astronomers","Scientists","Engineers","Biochemists"],"C",3,0,"508018a0311b",1],["A company develops a stronger plastic for packaging materials. Which branch is most directly involved?",["Biochemistry","Polymer Chemistry","Geochemistry","Nuclear Chemistry"],"B",3,1,"e315475080ca",1],["Why would a chemist use analytical instruments?",["To increase production only","To identify and measure substances","To study stars","To design bridges"],"B",3,1,"f5eb3e230b39",1],["Which activity represents engineering rather than science?",["Studying atomic structure","Investigating bond formation","Designing a chemical manufacturing plant","Discovering a new chemical reaction"],"C",3,0,"3df6e46dacaf",1],["A team of researchers is investigating how a new type of plastic waste interacts with seawater minerals over time. Which interdisciplinary field of chemistry would be most appropriate to categorize this study?",["Nuclear Chemistry","Geochemistry","Organic Chemistry","Analytical Chemistry"],"B",3,0,"7288438803ec",1],["A researcher investigates why iron rusts in the presence of air and moisture. This activity represents:",["Science","Engineering","Marketing","Technology"],"A",3,0,"f7f396d438da",1],["A student wants to determine whether a new fertilizer increases crop yield. Which factor should remain constant throughout the experiment?",["Type of fertilizer","Amount of crop produced","Soil type and water supply","Experimental conclusion"],"C",3,1,"dd0ef2fdc924",1],["Which situation best shows science, technology, and engineering working together?",["Memorizing chemical formulas","Building a water filtration system","Reading a chemistry book","Naming laboratory apparatus"],"B",3,0,"8ebd920f13de",1],["A chemist studying greenhouse gases and their effects on climate is working in:",["Organic Chemistry","Nuclear Chemistry","Astrochemistry","Environmental Chemistry"],"D",3,1,"d2a1b2f3b517",1],["An engineer designing the structure of a solar power plant is mainly applying:",["Engineering principles","Nuclear reactions","Organic reactions","Scientific investigation"],"A",3,1,"8e463f8850bf",1],["The relationship between atoms, bonds, and matter is primarily investigated in:",["Polymer Chemistry","Geochemistry","Industrial Chemistry","Physical Chemistry"],"D",3,0,"e8947f2d8165",1],["Which branch of chemistry deals with instruments and methods for identifying substances?",["Geochemistry","Analytical Chemistry","Astrochemistry","Polymer Chemistry"],"B",3,0,"514e2e96cd45",1],["When frying potatoes, a food technologist analyzes the oil to understand how it breaks down. How is this an example of chemistry in action?",["It utilizes engineering to change the taste of potatoes","It is an example of nuclear chemistry altering food","It proves that oil is an inorganic substance","It uses analytical methods to monitor the quality of organic molecules"],"D",3,0,"8db3d3ef7cc8",1],["Which of these is an example of an inorganic compound?",["Salt (NaCl)","A Carbohydrate","Plastic bag","A protein"],"A",3,0,"cb6dd852baf3",1],["If you are researching how greenhouse gases contribute to climate change, what is your primary field of study?",["Polymer Chemistry","Medicinal Chemistry","Nuclear Chemistry","Environmental Chemistry"],"D",3,0,"c64f3cffc3aa",1],["Why do we study chemistry?",["To apply concepts to new substances and technologies","To stop using all technology","To only study carbon compounds","To avoid studying matter"],"A",3,0,"2d81e176265f",1],["How does technology improve the work of a chemist in the pharmaceutical industry?",["By reducing the need for chemical Knowledge","By removing the need for scientists to conduct research","By automatically making every medicine safe","By allowing for the creation of completely new medicines using advanced analytical and identifying tools"],"D",3,1,"bfdfe00c89af",1],["A student claims that chemistry is important only in laboratories. Which example best disproves this claim?",["Using a telescope","Cooking food at home","Reading a history book","Playing football"],"B",3,1,"5742cfc87aae",1],["Which activity demonstrates the role of chemistry in agriculture?",["Producing fertilizers to improve crop yield","Designing road networks","Constructing buildings","Manufacturing furniture"],"A",3,0,"2f2e48319868",1],["Which of these is a valid interpretation of the \"Nature of Science\" in Chemistry?",["Science is purely for building machines","Science provides the foundational understanding to explain phenomena, while technology applies this to solve problems","Chemistry is a stagnant field with no interdisciplinary potential","Engineering is the study of matter and energy changes"],"B",3,0,"ac24c0d3a301",1],["Which of this best describes the \"Interdisciplinary\" nature of modern chemistry?",["It uses concepts from other fields like physics, biology, and environmental science","It refuses to use outside information","It only uses math","It is strictly limited to one textbook"],"A",3,0,"7b45365d6e55",1],["Why is the study of 'matter's interactions' essential to modern medicine?",["It helps in avoiding all chemical changes","It is only concerned with identifying carbon","It is irrelevant to energy considerations","It helps in understanding how drugs bond with biological targets"],"D",3,0,"0d1b2786b578",1],["Which branch would be most concerned with the toxicological pathways of heavy metal accumulation in organisms?",["Biochemistry","Organic Chemistry","Environmental Chemistry","Analytical Chemistry"],"C",3,0,"b250053290cc",1],["Why would a scientist investigating the \"Middle Ages\" of chemical history need to distinguish between science and engineering?",["To prove engineering is older than science","To understand the evolution of how we explored nature versus how we built tools","To show that chemistry didn't exist in the past","It is not important"],"B",3,1,"add2967af34f",1],["Why would a study on the effect of volcanic gases on Earth's atmosphere be categorized as Geochemistry?",["Because volcanoes are only organic","Because it doesn't involve energy","Because it involves Earth materials and their chemical transformations","Because it uses only hand tools"],"C",3,0,"057235b16582",1],["A student concludes that a fertilizer is effective after testing it on only one plant. What is the major weakness in this conclusion?",["Lack of observation","Insufficient evidence","Incorrect measurements","Excessive experimentation"],"B",3,1,"958a99a52240",1],["If a substance is used as a medicine, which sub-fields of chemistry are likely to have collaborated on its development?",["Inorganic Chemistry and Engineering","Physical Chemistry","Organic Chemistry and Biochemistry","Only Analytical Chemistry"],"C",3,1,"9deb52b68b6a",1],["Which branch of chemistry provides the \"tools\" to verify that a manufacturer is not putting toxic chemicals in drinking water?",["Analytical Chemistry","Organic Chemistry","Inorganic Chemistry","Physical Chemistry"],"A",3,0,"381a651be6d4",1],["A scientist records all observations, including unexpected ones. This practice mainly helps to:",["Eliminate experimentation","Increase objectivity","Reduce accuracy","Save time"],"B",3,1,"ecb5343396f4",1],["Why are scientific conclusions often considered tentative?",["Scientists lack confidence","Experiments are unnecessary","Observations are always incorrect","New evidence can refine existing knowledge"],"D",3,0,"1c3a69fefb76",1],["A chemist studies the effect of temperature on reaction rates. The primary objective is to understand:",["Composition of matter","Chemical behavior of matter","Origin of the universe","Manufacturing processes"],"B",3,1,"c6f80fdd41c1",1],["Which characteristic distinguishes science from personal opinion?",["Evidence-based reasoning","Imagination","Creativity","Observation alone"],"A",3,0,"3132803ec152",1],["A researcher finds that repeated experiments produce conflicting results. The most appropriate action is to:",["Ignore the unusual results","Reevaluate the procedure and collect more data","Publish the first result obtained","Select the result that supports the hypothesis"],"B",3,0,"6abf335367fc",1],["Which branch would be least involved in investigating the composition of a newly discovered meteorite?",["Astrochemistry","Analytical Chemistry","Geochemistry","Medicinal Chemistry"],"D",3,0,"17132357d1a4",1],["A chemist develops a new drug, an engineer designs a machine to manufacture it, and a company produces it on a large scale. Which sequence correctly represents the process?",["Technology → Science → Engineering","Science → Engineering → Technology","Engineering → Technology → Science","Technology → Engineering → Science"],"B",3,1,"f12b0bd2a016",1],["Which branch of chemistry would be most useful for a geologist analyzing the composition of ores?",["Geochemistry","Biochemistry","Organic Chemistry","Theoretical Chemistry"],"A",3,0,"a1e9e20f8c0e",1],["Which situation best demonstrates that chemistry contributes to the quality of human life?",["Discovery of a distant galaxy","Development of water purification techniques","Mapping ocean currents","Measuring earthquake intensity"],"B",3,0,"343ef78588b4",1],["Which branch of chemistry would most likely cooperate with environmental scientists to monitor toxic substances in a river?",["Astrochemistry","Polymer Chemistry","Industrial Chemistry","Analytical Chemistry"],"D",3,0,"423f3f24df1f",1],["A chemical process works well in the laboratory but fails during large-scale production. The problem is most likely addressed by:",["Historians","Chemical Engineers","Geologists","Astronomers"],"B",3,0,"2c4b02d14387",1],["Why is it important for scientific experiments to be reproducible?",["To verify the reliability of results","To reduce the need for observations","To eliminate hypotheses","To increase the cost of research"],"A",3,0,"f585ee54702d",1],["A scientist studies the chemicals present in ancient fossils to understand past life on Earth. This investigation combines chemistry with:",["Literature and Art","Astronomy and Music","Archaeology and Biology","Economics and Commerce"],"C",3,1,"c5bd3b36d856",1],["A researcher investigating a disease first identifies the chemicals involved and then develops a treatment. This sequence shows that:",["Discoveries occur without research","Technology always comes before science","Engineering replaces chemistry","Application often follows scientific understanding"],"D",3,0,"ab9eebd1d251",1],["Which characteristic of science allows knowledge to improve over time?",["Refusal to accept new ideas","Dependence on authority","Continuous testing and evaluation of evidence","Memorization of facts"],"C",3,0,"3ff0126ad594",1],["A team of scientists from different fields works together to solve a water contamination problem. This approach highlights:",["The importance of interdisciplinary collaboration","The independence of scientific disciplines","The replacement of science by technology","The limitations of chemistry"],"A",3,0,"a3e1aa28660f",1],["The discovery of synthetic fertilizers has significantly increased food production. This example best illustrates the impact of chemistry on:",["Astronomy","Agriculture","Literature","Transportation"],"B",3,0,"5b53e83636d9",1],["A scientist proposes an explanation for a phenomenon. Before it can be widely accepted, it must:",["Be memorized by students","Be approved by engineers","Be tested repeatedly","Be printed in textbooks"],"C",3,1,"99e2df45e6ee",1],["A chemist measures how air pollutants from factories affect rainwater. This work belongs to:",["Organic Chemistry","Nuclear Chemistry","Astrochemistry","Environmental Chemistry"],"D",3,1,"d2a1b2f3b517",0],["A medicine that works in a small lab trial must now be made in tonnes in a factory. Which experts mainly solve this scale-up problem?",["Historians","Chemical engineers","Geologists","Astronomers"],"B",3,1,"2c4b02d14387",0],["Studying how enzymes break down food inside the stomach is part of:",["Physical Chemistry","Inorganic Chemistry","Biochemistry","Analytical Chemistry"],"C",3,1,"32e098ce7d6e",0],["A scientist examines rocks and minerals to find which elements they contain. This branch is:",["Geochemistry","Biochemistry","Polymer Chemistry","Theoretical Chemistry"],"A",3,0,"a1e9e20f8c0e",0],["A laboratory tests a water sample to find exactly which metals are present and in what amounts. This is:",["Analytical Chemistry","Astrochemistry","Organic Chemistry","Geochemistry"],"A",3,1,"514e2e96cd45",0],["Before a new scientific idea is accepted, other scientists must:",["memorise it","test it repeatedly and get the same results","publish it in a newspaper","vote on it"],"B",3,0,"99e2df45e6ee",0],["Modern chemistry uses ideas from physics, biology and environmental science. This shows that chemistry is:",["interdisciplinary","outdated","limited to laboratories","only about metals"],"A",3,0,"7b45365d6e55",0],["Studying the chemicals in meteorites and distant stars is called:",["Astrochemistry","Biochemistry","Geochemistry","Food Chemistry"],"A",3,0,"514e2e96cd45",0],["Which branch of chemistry essentially dictates the \"how and why\" of chemical reactions?",["Physical Chemistry","Analytical Chemistry","Biochemistry","Geochemistry"],"A",5,0,"c6bb14edf0b6",1],["A researcher is studying the chemical reactions that happen during the production of steel on a massive scale. This is a clear application of:",["Analytical Chemistry","Organic Chemistry","Biochemistry","Industrial Chemistry"],"D",5,0,"45c379fa4212",1],["A researcher investigating acid rain would most likely need knowledge from:",["Environmental chemistry and analytical chemistry","Astrochemistry and geology only","Polymer chemistry only","Nuclear chemistry only"],"A",5,0,"11701f6b46c9",1]]$j$::jsonb, true);
